const fs = require("fs");
const path = require("path");
const { withAppBuildGradle, withDangerousMod } = require("expo/config-plugins");

// ---------------------------------------------------------------------------
// Android release performance.
//
// Two changes, both of which have to be a config plugin rather than a hand edit
// because android/ is gitignored and regenerated by `expo prebuild` — the same
// reason withUpiQueries and withNetworkSecurityConfig exist.
//
//   1. ABI FILTER on release. The release APK shipped four ABIs
//      (arm64-v8a, armeabi-v7a, x86, x86_64) at ~105 MB. The x86 pair exists
//      for emulators; no phone in the Play install base runs them. Debug keeps
//      every ABI so emulator development is untouched.
//
//      NOTE ON AABs: Play already splits an AAB per-ABI, so this does not
//      change what a user downloads — it changes what is BUILT and uploaded,
//      which is build time, CI minutes and Play storage. The download win is
//      real only for the universal APK (build-android.sh), which is the
//      artifact people sideload.
//
//   2. BASELINE PROFILE. AGP picks up app/src/main/baseline-prof.txt
//      automatically and compiles it into assets/dexopt/baseline.prof. The
//      shipped build had a 2,366-byte R8 stub there; RedotPay ships 12 KB and
//      Tangem 28 KB of real profile. A baseline profile is AOT-compiled at
//      install time, so the classes on the startup path skip the interpreter
//      on first run — it is the single largest cold-start lever available to
//      this app.
// ---------------------------------------------------------------------------

/** ABIs built for release. Add "x86_64" back if Chromebook support is needed. */
const RELEASE_ABIS = ["arm64-v8a", "armeabi-v7a"];

const ABI_BLOCK = `
    // --- injected by plugins/withAndroidPerformance.js ---
    // Release ships ARM only; debug keeps every ABI so emulators still work.
    buildTypes {
        release {
            ndk {
                abiFilters ${RELEASE_ABIS.map((a) => `"${a}"`).join(", ")}
            }
        }
    }
    // --- end injected ---
`;

function withReleaseAbiFilter(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== "groovy") {
      throw new Error(
        "withAndroidPerformance: app/build.gradle is not Groovy; the ABI filter was not applied."
      );
    }
    if (cfg.modResults.contents.includes("withAndroidPerformance.js")) return cfg;

    // Anchor on the `android {` block opener. Matching the first occurrence of
    // a line that is exactly `android {` avoids hitting `androidResources {`
    // or a comment mentioning android.
    const anchor = /^android\s*\{\s*$/m;
    if (!anchor.test(cfg.modResults.contents)) {
      throw new Error(
        "withAndroidPerformance: could not find the `android {` block in app/build.gradle."
      );
    }
    cfg.modResults.contents = cfg.modResults.contents.replace(
      anchor,
      (m) => `${m}\n${ABI_BLOCK}`
    );
    return cfg;
  });
}

/**
 * Copy the baseline profile into the generated Android project.
 *
 * Source of truth is android-profile/baseline-prof.txt in the repo, so the
 * profile is version-controlled and reviewable — unlike the generated android/
 * tree, which is disposable.
 */
function withBaselineProfile(config) {
  return withDangerousMod(config, [
    "android",
    async (cfg) => {
      const source = path.join(cfg.modRequest.projectRoot, "android-profile", "baseline-prof.txt");
      if (!fs.existsSync(source)) {
        // Loud, not silent. A missing profile is the exact failure this plugin
        // exists to prevent, and a warning in a 4,000-line build log is not a
        // signal anybody reads.
        throw new Error(
          `withAndroidPerformance: baseline profile missing at ${source}. ` +
            `Restore it or regenerate with the macrobenchmark module (see android-profile/README.md).`
        );
      }
      const destDir = path.join(cfg.modRequest.platformProjectRoot, "app", "src", "main");
      fs.mkdirSync(destDir, { recursive: true });
      fs.copyFileSync(source, path.join(destDir, "baseline-prof.txt"));
      return cfg;
    },
  ]);
}

module.exports = function withAndroidPerformance(config) {
  return withBaselineProfile(withReleaseAbiFilter(config));
};
